const initials=n=>n.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const logoSource=n=>{const mapped=logoFiles[n];if(mapped)return `assets/firm-logos/${mapped}`;const directory=TRUSTPILOT_FIRMS.find(f=>f.name===n),fallback=directory?.logo||directory?.logo_file;if(!fallback)return '';return fallback.startsWith('assets/')?fallback:`assets/firm-logos/${fallback}`};
const logo=n=>{const src=logoSource(n);return src?`<span class="logo-wrap firm-logo-frame"><img class="firm-logo" src="${src}" alt="${n} logo" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="firm-initial" hidden aria-label="${n}">${initials(n)}</span></span>`:`<span class="logo-wrap firm-logo-frame"><span class="firm-initial" aria-label="${n}">${initials(n)}</span></span>`};
const platformFiles={'cTrader':{file:'ctrader.png',label:'cTrader'},'MT5':{file:'mt5.png',label:'MetaTrader 5'},'MT4':{file:'mt4.png',label:'MetaTrader 4'},'Match-Trader':{file:'mt4.png',label:'MetaTrader 4'},'DXtrade':{file:'dxtrade.png',label:'DXtrade'}};
const platformIcon=p=>{const item=platformFiles[p];return item?`<span class="platform" title="${item.label}" aria-label="${item.label}"><img src="assets/platforms/${item.file}" alt="" aria-hidden="true"></span>`:''};
const promo=pct=>pct==null||Number(pct)<=0?'<span class="asset-tag">—</span>':`<span class="promo"><span class="pct">${pct}% OFF</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span>`;
let offerPage=0,videoIndex=0,market='forex',view='firms',currentFilter='popular',query='',sortKey='rank',sortDir='asc';
const favorites=new Set();
const toast=document.querySelector('#toast');
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),1600)}
async function copyCode(){let copied=false;try{await navigator.clipboard.writeText('LENZ');copied=true}catch(_){const t=document.createElement('textarea');t.value='LENZ';t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();try{copied=document.execCommand('copy')}catch(__){copied=false}t.remove()}showToast(copied?'Code copied':'Copy unavailable — code is LENZ')}
function renderDots(id,count,index,attr){document.querySelector(id).innerHTML=Array.from({length:count},(_,i)=>`<button class="carousel-dot ${i===index?'on':''}" type="button" ${attr}="${i}" aria-label="Go to ${i+1}" aria-current="${i===index?'true':'false'}"></button>`).join('')}
function offerTopCard(x){return `<article class="offers-top-card" data-offer-name="${safe(x.name)}">${logo(x.name)}<div><strong>${x.name}</strong>${trustpilotBadge(x.name)}</div>${promo(x.promoPct)}</article>`}
function featuredMarketFirms(){const offerByName=new Map(forexOffers().map(x=>[x.name,x]));return [...categoryTrustpilotFirms()].sort((a,b)=>(b.trustpilotRating??-1)-(a.trustpilotRating??-1)||(b.trustpilotReviews??-1)-(a.trustpilotReviews??-1)||a.name.localeCompare(b.name)).slice(0,6).map(f=>{const offer=offerByName.get(f.name);return {name:f.name,promoPct:offer?Number.parseFloat(offer.discount)||null:null}})}
function renderOffers(){const featured=featuredMarketFirms(),shift=(offerPage*3)%Math.max(1,featured.length),list=[...featured.slice(shift),...featured.slice(0,shift)];document.querySelectorAll('.panel-head h2,.offers-top-title h2').forEach(h=>{if(h.closest('.futures-panel,.offers-top-panel.futures'))return;h.textContent=`Exclusive September ${marketLabel()} Offers 🔥`});document.querySelectorAll('.futures-panel .panel-head h2,.offers-top-panel.futures .offers-top-title h2').forEach(h=>h.textContent=`Most Popular ${marketLabel()} Prop Firms`);document.querySelector('#offerGrid').innerHTML=list.length?list.map(x=>`<article class="offer">${logo(x.name)}<div><strong class="${x.name==='BrightFunded'?'fit-name':''}">${x.name}</strong>${trustpilotBadge(x.name)}</div>${promo(x.promoPct)}</article>`).join(''):'<div class="offer-empty">No verified offers are available for this category.</div>';renderDots('#offerDots',2,offerPage,'data-offer-dot');const top=document.querySelector('#offersTopGrid');if(top){top.innerHTML=list.length?list.slice(0,6).map(offerTopCard).join(''):'<div class="offer-empty">No verified offers are available for this category.</div>';renderDots('#offersTopDots',2,offerPage,'data-offer-dot')}}
function popularMarketFirms(){return [...categoryTrustpilotFirms()].sort((a,b)=>(b.trustpilotRating??-1)-(a.trustpilotRating??-1)||(b.trustpilotReviews??-1)-(a.trustpilotReviews??-1)).slice(0,3).map(x=>({name:x.name,promoPct:0}))}
function futuresMarkup(){return popularMarketFirms().map((x,i)=>{const t=trustpilotFor(x.name);return `<div class="offers-future-row"><span class="medal" aria-label="${['Gold','Silver','Bronze'][i]} trophy"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v3h3v2c0 3-1.7 5-4.5 5.7A5 5 0 0 1 13 16v2h4v3H7v-3h4v-2a5 5 0 0 1-2.5-2.3C5.7 13 4 11 4 8V6h3V3Zm10 5V6h1v2c0 1.4-.6 2.4-1.7 3 .4-.9.7-1.9.7-3ZM7.7 11C6.6 10.4 6 9.4 6 8V6h1v2c0 1.1.2 2.1.7 3Z"/></svg></span>${logo(x.name)}<div><strong>${x.name}</strong><span class="ratepill">${t?.trustpilotRating?.toFixed(1)??'—'} <span class="rating-out-of">/ 5</span>${t?.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()}`:''}</span></div></div>`}).join('')}
function renderFutures(){const rows=popularMarketFirms();document.querySelector('#futuresList').innerHTML=rows.map((x,i)=>{const t=trustpilotFor(x.name);return `<div class="future"><span class="medal" aria-label="${['Gold','Silver','Bronze'][i]} trophy"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v3h3v2c0 3-1.7 5-4.5 5.7A5 5 0 0 1 13 16v2h4v3H7v-3h4v-2a5 5 0 0 1-2.5-2.3C5.7 13 4 11 4 8V6h3V3Zm10 5V6h1v2c0 1.4-.6 2.4-1.7 3 .4-.9.7-1.9.7-3ZM7.7 11C6.6 10.4 6 9.4 6 8V6h1v2c0 1.1.2 2.1.7 3Z"/></svg></span>${logo(x.name)}<div><strong>${x.name}</strong><span class="ratepill">${t?.trustpilotRating?.toFixed(1)??'—'} <span class="rating-out-of">/ 5</span>${t?.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()}`:''}</span></div></div>`}).join('');const panel=document.querySelector('#offersFuturesList');if(panel)panel.innerHTML=futuresMarkup()}
let offersFilter='exclusive',offersQuery='';
const expandedOfferGroups=new Set();
function displayDiscount(x){return x.discount==='Offer'?'PROMO':`${safe(x.discount)} <span>OFF</span>`}
function offerRow(x,moreCount=0){const t=trustpilotFor(x.name);const rating=t?.trustpilotRating==null?'Trustpilot —':`${t.trustpilotRating.toFixed(1)} <span class="rating-out-of">/ 5</span>${t.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()} reviews`:''}`;const more=moreCount?`<button class="more-btn" type="button" data-offer-more data-more-count="${moreCount}" aria-expanded="false">More ${moreCount} <span aria-hidden="true">⌄</span></button>`:'';return `<article class="offer-row" data-offer-name="${safe(x.name.toLowerCase())}"><div class="offer-discount"><span class="offer-flame" aria-hidden="true">◆</span><b>${displayDiscount(x)}</b>${x.extra?'<span class="free-account">＋ FREE ACCOUNT</span>':''}</div><div class="offer-main"><div class="offer-firmline">${logo(x.name)}<div><h3>${safe(x.name)}</h3><span class="offer-rating">${rating}</span></div></div><p class="offer-desc">${safe(x.description)}</p></div><div class="offer-actions"><span class="offer-code"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span><button class="apply-btn" type="button" data-apply data-buy-link="${safe(x.buyLink)}">Apply</button><span class="offer-timing">Offer snapshot · Sep 21, 2026</span>${more}</div></article>`}
function offerGroup(items){const name=items[0].name,moreCount=items.length-1,expanded=expandedOfferGroups.has(name);return `<section class="offer-group ${expanded?'expanded':''}" data-offer-group="${safe(name)}">${offerRow(items[0],moreCount)}${moreCount?`<div class="offer-additional-rows" ${expanded?'':'hidden'}>${items.slice(1).map(x=>offerRow(x)).join('')}</div>`:''}</section>`}
function renderOfferList(){const all=forexOffers().filter(x=>(offersFilter!=='extra'||x.extra)&&x.name.toLowerCase().includes(offersQuery));const groups=[];all.forEach(x=>{let group=groups.find(items=>items[0].name===x.name);if(!group){group=[];groups.push(group)}group.push(x)});const label=offersFilter==='extra'?'Extra Account Offers':offersFilter==='all'?'All Offers':'Exclusive Offers';document.querySelector('#offersListTitle').innerHTML=`${label} <span>${all.length}</span>`;document.querySelector('#offersOfferList').innerHTML=all.length?groups.map(offerGroup).join(''):'<div class="offer-empty">No offers match your search.</div>';document.querySelectorAll('[data-offer-more]').forEach(button=>{const expanded=expandedOfferGroups.has(button.closest('.offer-group').dataset.offerGroup);button.setAttribute('aria-expanded',String(expanded));button.innerHTML=`More ${button.dataset.moreCount} <span aria-hidden="true">${expanded?'⌃':'⌄'}</span>`})}
function sourceFirms(){const category=categoryTrustpilotFirms(),sourceOrder=new Map(category.map((t,index)=>[t.name,index])),ranked=[...category].sort((a,b)=>{const ar=firms.find(f=>f.name===a.name)?.rank,br=firms.find(f=>f.name===b.name)?.rank;if(ar!=null&&br!=null)return ar-br;if(ar!=null)return -1;if(br!=null)return 1;return sourceOrder.get(a.name)-sourceOrder.get(b.name)});return ranked.map((t,index)=>{const detailed=firms.find(f=>f.name===t.name);const profile=PROFILE_SOURCE.find(p=>p.name===t.name);const offer=OFFER_CATALOG.find(o=>o.name===t.name);return {...(detailed||{}),buyLink:detailed?.buyLink||CHECKOUT_LINKS[t.name]||offer?.buyLink||'',assets:detailed?.assets??profile?.assets??[],country:detailed?.country??profile?.country??null,favorites:detailed?.favorites||0,flag:detailed?.flag||profile?.country_code?.toLowerCase()||'',maxAllocation:detailed?.maxAllocation??profile?.max_allocation??null,name:t.name,platforms:detailed?.platforms??profile?.platforms??[],promoPct:detailed?.promoPct??(offer?Number.parseFloat(offer.discount)||null:null),rank:index+1,rating:t.trustpilotRating,reviews:t.trustpilotReviews||0,years:detailed?.years??profile?.years??null}})}
function numericAllocation(v){if(!v)return -1;const n=parseFloat(v.replace(/[^0-9.]/g,''));return v.includes('M')?n*1000000:n*1000}
function filteredFirms(){let list=sourceFirms().filter(f=>f.name.toLowerCase().includes(query));if(currentFilter==='favorite')list=list.filter(f=>favorites.has(f.name));if(currentFilter==='new')list=list.filter(f=>typeof f.years==='number'&&f.years<=2);const val=(f,key)=>key==='allocation'?numericAllocation(f.maxAllocation):key==='years'?parseFloat(f.years)||-1:Number(f[key]??-1);return [...list].sort((a,b)=>{const av=val(a,sortKey),bv=val(b,sortKey);if(av===bv)return a.rank-b.rank;return sortDir==='asc'?av-bv:bv-av})}
function rankCard(f){const hasCountry=!!f.country,assets=(f.assets||[]).filter(a=>market==='forex'?!['Crypto','Futures'].includes(a):a===marketLabel()),platforms=f.platforms||[],t=trustpilotFor(f.name),count=t?.trustpilotReviews==null?null:Number(t.trustpilotReviews);return `<article class="rank-card"><span class="rank-num">${f.rank<=3?'★':f.rank}</span><div class="firm-cell">${logo(f.name)}<div><strong>${safe(f.name)}</strong>${f.favorites?`<span class="fav-count">♥ ${Number(f.favorites).toLocaleString()}</span>`:''}</div><button class="favorite ${favorites.has(f.name)?'on':''}" type="button" data-favorite="${safe(f.name)}" aria-label="Favorite ${safe(f.name)}">${favorites.has(f.name)?'♥':'♡'}</button></div><div class="rating-cell">${t?.trustpilotRating==null?'<span aria-label="Trustpilot score unavailable">—</span>':`<span class="score">${t.trustpilotRating.toFixed(1)}</span><span class="rating-out-of">/ 5</span>`}<span class="review">${count==null?'—':`${count.toLocaleString()} Trustpilot reviews`}</span></div><div class="country-cell">${hasCountry?`<img src="assets/flags/${f.flag}.png" alt="${safe(f.country)} flag"><span>${safe(f.country)}</span>`:'<span>—</span>'}</div><div class="years-ring"><b>${f.years??'—'}</b></div><div class="taglist">${assets.length?assets.map(a=>`<span class="asset-tag">${safe(a)}</span>`).join(''):'<span class="asset-tag">—</span>'}</div><div class="platforms">${platforms.length?platforms.map(platformIcon).join(''):'<span class="asset-tag">—</span>'}</div><div class="alloc"><b>${f.maxAllocation??'—'}</b>${f.maxAllocation?'<span class="bar"><i></i></span>':''}</div>${promo(f.promoPct)}<a class="firm-action" href="#page-offers" data-page="offers">Offers</a></article>`}
function altCard(f,type){const heart=`<button class="favorite ${favorites.has(f.name)?'on':''}" type="button" data-favorite="${safe(f.name)}" aria-label="Favorite ${safe(f.name)}">${favorites.has(f.name)?'♥':'♡'}</button>`;if(type==='challenges'){const assets=(f.assets||[]).filter(a=>market==='forex'?!['Crypto','Futures'].includes(a):a===marketLabel());return `<article class="alt-card">${logo(f.name)}<div><h3>${safe(f.name)}</h3><p>Rating ${f.rating==null?'—':`${f.rating} / 5`}</p><p>${f.maxAllocation?`Maximum allocation ${safe(f.maxAllocation)}`:'Maximum allocation —'}</p></div>${promo(f.promoPct)}<div class="taglist wide">${assets.length?assets.map(a=>`<span class="asset-tag">${safe(a)}</span>`).join(''):'<span class="asset-tag">Challenge data unavailable</span>'}</div></article>`}if(type==='reviews')return `<article class="alt-card">${logo(f.name)}<div><h3>${safe(f.name)}</h3>${trustpilotBadge(f.name)}</div>${heart}<div class="wide">${promo(f.promoPct)}</div></article>`;return ''}
function offerViewItems(){return featuredMarketFirms()}
function renderMain(){document.querySelector('#favTotal').textContent=favorites.size;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const head=document.querySelector('#rankHead'),list=document.querySelector('#rankList');if(view==='firms'){head.style.display='';list.className='';const data=filteredFirms();list.innerHTML=data.length?data.map(rankCard).join(''):'<div class="empty-state">No firms match this view.</div>'}else{head.style.display='none';list.className='alt-grid';let data=view==='offers'?offerViewItems():filteredFirms();data=data.filter(f=>f.name.toLowerCase().includes(query));list.innerHTML=data.length?(view==='offers'?data.map(f=>`<article class="alt-card">${logo(f.name)}<div><h3>${f.name}</h3>${trustpilotBadge(f.name)}<p>Use code LENZ</p></div>${promo(f.promoPct)}</article>`).join(''):data.map(f=>altCard(f,view)).join('')):'<div class="empty-state">No firms match this view.</div>'}document.querySelectorAll('[data-sort]').forEach(b=>b.classList.toggle('on',b.dataset.sort===sortKey));document.querySelector('#viewAll').style.display=query||currentFilter!=='all'?'flex':'none'}
function renderVideos(){const ordered=[...videos.slice(videoIndex),...videos.slice(0,videoIndex)];document.querySelector('#videoRail').innerHTML=ordered.map(v=>`<div class="video"><button class="video-facade" type="button" data-video-play="${v[1]}" aria-label="Play ${safe(v[0])}"><img src="assets/video-thumbnails/${v[1]}.jpg" alt="Thumbnail for ${safe(v[0])}"><span class="video-play" aria-hidden="true">▶</span></button></div>`).join('');renderDots('#videoDots',videos.length,videoIndex,'data-video-dot')}
function playVideo(button){const id=button.dataset.videoPlay;const frame=document.createElement('iframe');frame.src=`https://www.youtube.com/embed/${id}?autoplay=1`;frame.title=button.getAttribute('aria-label')||'YouTube video';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;button.replaceWith(frame)}
function updateMarketCopy(){
  const label=marketLabel(),categoryFirms=categoryTrustpilotFirms();
  document.body.dataset.marketTheme=market;
  document.querySelectorAll('[data-market]').forEach(b=>{const active=b.dataset.market===market;b.classList.toggle('on',active);b.setAttribute('aria-pressed',String(active))});
  document.querySelector('#marketEmpty').hidden=true;
  document.querySelectorAll('.favorites-count').forEach(el=>{if(el.firstChild)el.firstChild.textContent=`${label} firms `});
  const favoriteInfo=document.querySelector('.favorites-info p');if(favoriteInfo)favoriteInfo.textContent=`This list ranks the ${label} firms covered by Prop Firm Lenz using the Trustpilot rating snapshot shown for each firm. Firms with unavailable or withheld scores appear after rated firms, and the review-volume bars use the largest verified review count in this list as the scale.`;
  const compare=document.querySelector('#comparePage .page-intro h1');if(compare)compare.textContent=`Compare ${label} Prop Firms`;
  const compareLabel=document.querySelector('#comparePage .page-stat span');if(compareLabel)compareLabel.textContent=`${label} firms`;
  const compareSubscribe=document.querySelector('#comparePage .static-subscribe h2');if(compareSubscribe)compareSubscribe.textContent=`Subscribe for new ${label} comparison updates`;
  const spreadsTitle=document.querySelector('#spreadsPage .page-intro h1');if(spreadsTitle)spreadsTitle.textContent=`Best ${label} Prop Firm Spreads`;
  const spreadFilter=document.querySelector('.spreads-filters .spread-filter.on');if(spreadFilter)spreadFilter.textContent=label;
  const spreadsCount=document.querySelector('.spreads-count');if(spreadsCount&&spreadsCount.firstChild)spreadsCount.firstChild.textContent=`${label} firms `;
  const spreadSubscribe=document.querySelector('#spreadsPage .static-subscribe h2');if(spreadSubscribe)spreadSubscribe.textContent=`Subscribe for new ${label} spread research`;
  const payoutTitle=document.querySelector('.payout-hub-head h1');if(payoutTitle)payoutTitle.textContent=`${label} Prop Firm Payouts Tracker`;
  const payoutIntro=document.querySelector('.payout-hub-head p');if(payoutIntro)payoutIntro.textContent=`Compare payout times, payout totals, and payout history across matched ${label} firms. View firm-level payout trends and recent payouts.`;
  const resourceChallenge=document.querySelector('#resources .resource:nth-child(3) p');if(resourceChallenge){const count=CHALLENGES_DATA.filter(x=>firmInMarket(x.firm)).length;resourceChallenge.textContent=count?`Compare the ${count} tracked ${label} challenge records by account size, steps, targets, loss limits, payout frequency, and price.`:`Browse ${label} firms in the same challenge comparison layout. Fields without verified challenge data are shown as unavailable.`}
  document.querySelector('#heroFirmCount').textContent=categoryFirms.length.toLocaleString();document.querySelector('#heroChallengeLabel').textContent=`${label} Challenges`;document.querySelector('#heroOfferLabel').textContent='Tracked Offers';document.querySelector('#faqTitle').textContent=`Homepage FAQ (${label})`
}
