function reviewRow(f,maxReviews,rank){const count=f.trustpilotReviews==null?null:Number(f.trustpilotReviews),score=f.trustpilotRating,width=count!=null&&count>0?Math.max(2,Math.min(100,count/maxReviews*100)):0,href=count==null?'':(TRUSTPILOT_URLS[f.name]||'');return `<article class="review-row"><div class="review-firm" data-label="Firm">${reviewFirmLogo(f.name)}<div><strong>${safe(f.name)}</strong>${score==null?'':reviewStars(score)}</div></div><div class="review-count" data-label="Trustpilot reviews"><b>${count==null?'—':count.toLocaleString()}</b><span class="bar"><i style="width:${width}%"></i></span></div><div data-label="TrustScore"><span class="trustscore">${score==null?'—':`<span class="star">★</span>${score.toFixed(1)}`}</span></div><div data-label="Rank">${score==null?'—':`<span class="review-rank-number">${rank}</span>`}</div>${href?`<a class="review-link" href="${safe(href)}" target="_blank" rel="noopener noreferrer">View Reviews</a>`:'<span class="review-link">Unavailable</span>'}</article>`}
