function openFirmReviews(name){const firm=TRUSTPILOT_FIRMS.find(f=>f.name===name);if(!firm)return;const allItems=firmReviewItems(name),items=reviewFlag==='all'?allItems:allItems.filter(r=>reviewFlag==='funded'?r.funded===true:r.paidOut===true);document.querySelector('#firmReviewsTitle').textContent=`${name} Reviews`;const tp=firm.trustpilotRating==null?'<div class="review-summary"><b>—</b><span>External Trustpilot data is unavailable or withheld.</span></div>':`<div class="review-summary"><b>${firm.trustpilotRating.toFixed(1)} / 5</b><span>External Trustpilot data${Number(firm.trustpilotReviews)>0?` · ${Number(firm.trustpilotReviews).toLocaleString()} reviews`:' · review count unavailable'}</span></div>`;const pfl=items.length?`<div class="pfl-review-list">${items.map(r=>`<article class="pfl-review-item"><header><strong>${safe(r.title||'Prop Firm Lenz review')}</strong><span>${safe(r.rating??'—')} / 5</span></header><p>${safe(r.body||r.text||'')}</p></article>`).join('')}</div>`:`<div class="reviews-empty">${allItems.length?'No Prop Firm Lenz reviews match this filter.':'No Prop Firm Lenz reviews yet.'}</div>`;document.querySelector('#firmReviewsBody').innerHTML=`${tp}<h3>Prop Firm Lenz reviews</h3>${pfl}`;openModal('#firmReviewsModal')}

