function profileOverviewSection(f){const parts=[];if(f.description)parts.push(`<div class="profile-subsection"><span class="profile-label">About ${safe(f.name)}</span><p>${safe(f.description)}</p></div>`);if(f.features.length)parts.push(`<div class="profile-subsection"><span class="profile-label">Verified highlights</span><ul class="profile-feature-list">${f.features.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></div>`);if(f.platforms.length||f.assets.length)parts.push(`<div class="profile-subsection profile-overview-grid">${f.platforms.length?`<div><span class="profile-label">Platforms</span><div class="profile-tags">${f.platforms.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}${f.assets.length?`<div><span class="profile-label">Instruments and assets</span><div class="profile-tags">${f.assets.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}</div>`);return parts.length?`<section class="profile-card" id="profile-overview"><h2>Firm Overview</h2>${parts.join('')}</section>`:''}
