function profileOffersSection(f){return f.offers.length?`<section class="profile-card" id="profile-offers"><h2>Offers</h2>${f.offers.map(o=>`<article class="profile-offer-card"><div><strong>${safe(o.discount)}</strong><p>${safe(o.description)}</p></div><span class="profile-code-pill"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span></article>`).join('')}</section>`:''}
function profilePayoutSection(d){return d.payouts.length?`<section class="profile-card" id="profile-payouts"><h2>Payout Policy</h2><div class="profile-payout-grid">${d.payouts.map(x=>`<article class="profile-activity-item"><h3>${safe(x.period)} payouts</h3><span class="profile-activity-value">${profileValue(x.total)}</span><p>${profileValue(x.count)} tracked payouts${x.largest?` · largest ${safe(x.largest)}`:''}</p></article>`).join('')}</div></section>`:''}
function profileReviewsSection(f,d){if(!d.hasReviews)return '';const trust=f.trustpilotRating!=null||f.trustpilotReviews!=null?`<article class="profile-activity-item"><h3>Trustpilot</h3><span class="profile-activity-value">${f.trustpilotRating==null?'—':`${Number(f.trustpilotRating).toFixed(1)} / 5`}</span><p>${f.trustpilotReviews==null?'Review count unavailable':`${Number(f.trustpilotReviews).toLocaleString()} reviews`}</p></article>`:'';const community=d.published.length?`<article class="profile-activity-item"><h3>Prop Firm Lenz reviews</h3><span class="profile-activity-value">${d.published.length.toLocaleString()}</span><p>Published community reviews</p></article>`:'';return `<section class="profile-card" id="profile-reviews"><h2>Reviews</h2><div class="profile-review-grid">${trust}${community}</div><button class="profile-review-btn" type="button" data-write-pfl-review="${safe(f.name)}" style="margin-top:12px">Write a review</button></section>`}
function profileSidebar(f,d){const categories=f.categories.map(x=>marketLabels[x]||x),facts=[['Category',categories.join(', ')],['Country',f.country],['Trustpilot',f.trustpilotRating==null?null:`${Number(f.trustpilotRating).toFixed(1)} / 5`],['Years in operation',f.years],['Maximum allocation',f.maxAllocation]].filter(x=>x[1]!=null&&x[1]!=='');return `<aside class="profile-sidebar">${f.buyLink?`<button class="profile-cta" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Start Trading Now!</button>`:''}<section class="profile-sidebar-card"><h2>Key facts</h2><dl class="profile-facts">${facts.map(([k,v])=>`<div><dt>${safe(k)}</dt><dd>${safe(v)}</dd></div>`).join('')}</dl></section>${f.offer?`<section class="profile-sidebar-card profile-sidebar-offer"><h2>Active offer</h2><strong>${safe(f.offer.discount)}</strong><p>${safe(f.offer.description)}</p><span class="profile-code-pill" style="margin-top:12px"><span>Code</span><button class="copy" type="button" data-copy="LENZ">LENZ ⧉</button></span></section>`:''}</aside>`}
function renderFirmProfile(name){const f=profileFirmFor(name),root=document.querySelector('#firmProfileContent');if(!f.trust&&!f.source){root.innerHTML='';return}const d=profileData(f),rating=f.rating==null?null:Number(f.rating),reviews=f.reviewsCount==null?null:Number(f.reviewsCount),tabs=[];if(d.hasOverview)tabs.push(['overview','Overview',null]);if(d.challenges.length)tabs.push(['challenges','Challenges',d.challenges.length]);if(d.hasReviews)tabs.push(['reviews','Reviews',f.trustpilotReviews??d.published.length]);if(f.offers.length)tabs.push(['offers','Offers',f.offers.length]);if(d.payouts.length)tabs.push(['payouts','Payouts',null]);if(!tabs.length){root.innerHTML=`<nav class="profile-action-row" aria-label="Firm profile actions"><button class="profile-action-pill profile-action-back" type="button" data-profile-back aria-label="Back">←</button><span class="profile-action-pill profile-action-firm">${logo(f.name)}<span>${safe(f.name)}</span></span><button class="profile-action-pill profile-action-favorite" type="button" data-profile-notice="Favorites">♡ Set as Favorite</button><span class="profile-action-spacer"></span><button class="profile-action-pill profile-action-review" type="button" data-profile-notice="Reviews">Leave a Review</button>${f.buyLink?`<button class="profile-action-pill profile-action-buy" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Buy</button>`:''}</nav><header class="profile-title-block"><div class="profile-title-main"><div class="profile-title-logo">${logo(f.name)}</div><div class="profile-title-copy"><h1>${safe(f.name)}</h1><p class="profile-offer-description">Details coming soon.</p></div></div></header>`;profileScrollSpyCleanup();return}if(!tabs.some(x=>x[0]===profileTab))profileTab=tabs[0][0];const facts=[['Country',f.country],['Trustpilot score',f.trustpilotRating==null?null:Number(f.trustpilotRating).toFixed(1)],['Years in operation',f.years],['Maximum allocation',f.maxAllocation]].filter(([,v])=>v!=null&&v!=='');const reviewLabel=reviews==null?'':`${reviews.toLocaleString()} reviews`;const promoLabel=profilePromoValue(f.promo);const promo=f.offer&&promoLabel?`<section class="profile-offer-banner"><div class="profile-offer-discount"><span class="profile-promo-flame" aria-hidden="true">♨</span><strong>${safe(promoLabel)}</strong></div><div><div class="profile-offer-identity">${logo(f.name)}<div><h2>${safe(f.name)}</h2><div class="profile-rating-line"><span class="stars">★★★★★</span>${rating==null?'':`<b>${rating.toFixed(1)}</b>`}${reviews==null?'':`<span>${reviews.toLocaleString()} reviews</span>`}</div></div></div><p class="profile-offer-description">${safe(f.offer.description)}</p></div><span class="profile-code-pill"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span></section>`:'';root.innerHTML=`<nav class="profile-action-row" aria-label="Firm profile actions"><button class="profile-action-pill profile-action-back" type="button" data-profile-back aria-label="Back">←</button><span class="profile-action-pill profile-action-firm">${logo(f.name)}<span>${safe(f.name)}</span></span><button class="profile-action-pill profile-action-favorite" type="button" data-profile-notice="Favorites">♡ Set as Favorite</button><span class="profile-action-spacer"></span><button class="profile-action-pill profile-action-review" type="button" data-profile-notice="Reviews">Leave a Review</button>${f.buyLink?`<button class="profile-action-pill profile-action-buy" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Buy</button>`:''}</nav><header class="profile-title-block"><div class="profile-title-main"><div class="profile-title-logo">${logo(f.name)}</div><div class="profile-title-copy"><h1>${safe(f.name)}</h1><div class="profile-rating-line">${rating==null?'':`<span class="stars">★★★★★</span><b>${rating.toFixed(1)}</b>`}${reviewLabel?`<span>${reviewLabel}</span>`:''}</div>${facts.length?`<div class="profile-title-facts">${facts.map(([k,v])=>`<div class="profile-title-fact"><span>${safe(k)}</span><b>${safe(v)}</b></div>`).join('')}</div>`:''}</div></div>${rating!=null||reviews!=null?`<div class="profile-rating-summary">${rating==null?'':`<b>${rating.toFixed(1)}</b><span class="stars">★★★★★</span>`}${reviews==null?'':`<small>${reviews.toLocaleString()} total reviews</small>`}</div>`:''}</header>${promo}<nav class="profile-tabs" aria-label="Firm profile sections">${tabs.map(([id,label,count])=>`<button class="${profileTab===id?'on':''}" type="button" data-profile-tab="${id}" aria-selected="${profileTab===id}">${label}${count==null?'':`<span class="profile-tab-count">${Number(count).toLocaleString()}</span>`}</button>`).join('')}</nav><h2 class="profile-details-heading">${safe(f.name)} Prop Firm Details</h2><div class="profile-layout"><nav class="profile-anchor-nav" aria-label="On this page">${tabs.map(([id,label])=>`<button class="${profileTab===id?'on':''}" type="button" data-profile-tab="${id}">${id==='overview'?'Firm Overview':id==='payouts'?'Payout Policy':label}</button>`).join('')}</nav><div class="profile-main">${profileOverviewSection(f)}${profileChallengesSection(f,d)}${profileOffersSection(f)}${profilePayoutSection(d)}${profileReviewsSection(f,d)}</div>${profileSidebar(f,d)}</div>`;bindProfileScrollSpy()}
let profileScrollSpyCleanup=()=>{};
function setProfileScrollSpyActive(id){if(!id)return;profileTab=id;document.querySelectorAll('.profile-tabs [data-profile-tab]').forEach(button=>{const active=button.dataset.profileTab===id;button.classList.toggle('on',active);button.setAttribute('aria-selected',String(active))});document.querySelectorAll('.profile-anchor-nav [data-profile-tab]').forEach(button=>{const active=button.dataset.profileTab===id;button.classList.toggle('on',active);if(active)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current')})}
function scrollToProfileSection(id){const target=document.querySelector(`#profile-${id}`);if(!target)return;setProfileScrollSpyActive(id);const header=document.querySelector('.site-head'),top=target.getBoundingClientRect().top+window.scrollY-(header?.offsetHeight||0)-14;window.scrollTo({top:Math.max(0,top),behavior:'smooth'})}
function bindProfileScrollSpy(){profileScrollSpyCleanup();const page=document.querySelector('#firmProfilePage'),nav=document.querySelector('.profile-anchor-nav');if(!page||!nav)return;const sections=[...nav.querySelectorAll('[data-profile-tab]')].map(button=>document.querySelector(`#profile-${button.dataset.profileTab}`)).filter(Boolean).sort((a,b)=>a.offsetTop-b.offsetTop);if(!sections.length)return;let frame=0;const update=()=>{frame=0;if(page.hidden)return;const header=document.querySelector('.site-head'),probe=(header?.offsetHeight||0)+14+Math.min(window.innerHeight*.3,220);let active=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=probe)active=section;else break}if(window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-2)active=sections[sections.length-1];setProfileScrollSpyActive(active.id.replace('profile-',''))};const queue=()=>{if(!frame)frame=requestAnimationFrame(update)};window.addEventListener('scroll',queue,{passive:true});window.addEventListener('resize',queue);profileScrollSpyCleanup=()=>{window.removeEventListener('scroll',queue);window.removeEventListener('resize',queue);if(frame)cancelAnimationFrame(frame);frame=0};requestAnimationFrame(update)}
function openFirmProfile(name){const canonical=profileCanonicalName(name);if(!trustpilotFor(canonical)&&!profileSourceFor(canonical))return;profileOriginHash=location.hash&&!location.hash.startsWith('#firm/')?location.hash:'#page-home';currentProfileSlug=profileSlugFor(canonical);profileTab='overview';openPage('firm-profile')}

function decorateFirmNames(){const names=new Map(TRUSTPILOT_FIRMS.map(x=>[x.name,x.name]));Object.keys(profileAliases).forEach(alias=>names.set(alias,profileAliases[alias]));document.querySelectorAll('main strong,main h2,main h3,main .firm-name-link').forEach(el=>{if(el.closest('#firmProfilePage'))return;const text=el.textContent.trim().replace(/\s+/g,' '),name=names.get(text);if(!name||el.dataset.firmProfile)return;el.dataset.firmProfile=name;el.classList.add('firm-name-profile-link');if(!/^(A|BUTTON)$/.test(el.tagName)){el.setAttribute('role','link');el.setAttribute('tabindex','0')}})}
const firmNameObserver=new MutationObserver(()=>decorateFirmNames());firmNameObserver.observe(document.querySelector('main'),{childList:true,subtree:true});

const payoutAliases={'Tradeify Futures':'Tradeify','MyFundedFutures':'My Funded Futures','BlueGuardian':'Blue Guardian','E8Markets':'E8 Markets','GoatFundedTrader':'Goat Funded Trader','GoatFundedFutures':'Goat Funded Futures','AlphaCapitalGroup':'Alpha Capital','FundedFuturesFamily':'Funded Futures Family','TopOneFutures':'Top One Futures','TopOneTrader':'Top One Trader','HolaPrime':'Hola Prime','YlosTrading':'Ylos Trading','Instantfunding':'Instant Funding'};
function payoutCanonicalName(name){return payoutAliases[name]||name}
function payoutTrustpilot(name){const canonical=payoutCanonicalName(name);return TRUSTPILOT_FIRMS.find(f=>f.name===canonical)||null}
function payoutCategoryFor(name){return trustpilotFor(payoutCanonicalName(name))?.category||null}
function payoutRowsForTimeframe(){let rows=[];if(payoutTimeframe==='latest_24h')rows=(PAYOUT_DATA.latest_24h||[]).map((r,i)=>({...r,_rank:i+1}));else if(payoutTimeframe==='weekly'||payoutTimeframe==='monthly')rows=(PAYOUT_DATA[payoutTimeframe]?.rows||[]).map((x,i)=>({firm:x.firm,methods:x.method,total:x.cells?.[2]??'—',count:x.cells?.[3]??'—',largest:'—',average:'—',median:'—',latest:'—',_rank:i+1}));else if(payoutTimeframe==='last_30d')rows=(PAYOUT_DATA.stats?.top5_30d||[]).map((x,i)=>({firm:x.firm,methods:'—',total:x.usd==null?'—':usd(x.usd),count:x.count==null?'—':whole(x.count),largest:'—',average:'—',median:'—',latest:'—',_rank:i+1}));return rows}
function payoutFirmRating(name){const f=payoutTrustpilot(name);if(!f||f.trustpilotRating==null||f.trustpilotReviews==null)return '<span class="payout-trustpilot empty">Trustpilot —</span>';return `<span class="payout-trustpilot"><b>${f.trustpilotRating.toFixed(1)}</b><span class="rating-out-of">/ 5</span><span>${Number(f.trustpilotReviews).toLocaleString()}</span></span>`}
function payoutFirm(name){const canonical=payoutCanonicalName(name);return `<div class="firm-cell">${logo(name)}<div class="payout-firm-meta"><button class="firm-name-link" type="button" data-payout-detail="${safe(name)}">${safe(canonical)}</button>${payoutFirmRating(name)}</div></div>`}
function payoutEmpty(){document.querySelector('#payoutView').innerHTML='<div class="payout-empty"><span>Payout data is updating…</span></div>'}
function payoutHeader(){if(typeof PAYOUT_DATA==='undefined'||!PAYOUT_DATA||!Object.keys(PAYOUT_DATA).length)return false;document.querySelector('#payoutUpdated').textContent=`Updated ${PAYOUT_DATA.captured_at} · figures update automatically and may not represent firms’ full payout volume`;return true}
function sortPayoutRows(rows){return [...rows].sort((a,b)=>{const get=(row,key)=>{if(key==='firm')return payoutCanonicalName(row.firm).toLowerCase();if(key==='rank')return row._rank;if(key==='reviews')return payoutTrustpilot(row.firm)?.trustpilotReviews??-1;if(key==='median')return moneyNumber(row.median_time??row.medianTime??row.median);return moneyNumber(row[key])};const av=get(a,payoutSort),bv=get(b,payoutSort);const result=typeof av==='string'?av.localeCompare(bv):av-bv;return payoutSortDir==='asc'?result:-result})}
function payoutSpeed(row){const time=row.median_time??row.medianTime??row.median;if(time==null||time===''||time==='—')return '<span class="payout-dash">—</span>';const raw=String(time),label=String(row.median_label||row.medianLabel||'').trim();const shown=label||'Recorded';const cls=shown.toLowerCase().replace(/\s+/g,'-');return `<span class="payout-time"><span class="payout-speed ${safe(cls)}">${safe(shown)}</span><b>${safe(raw)}</b></span>`}
function payoutGauge(value,max){const n=moneyNumber(value);if(!n||value==='—')return '<span class="payout-dash">—</span>';const deg=Math.max(8,Math.min(180,n/Math.max(max,1)*180));return `<span class="payout-gauge-wrap"><span class="payout-gauge" style="--gauge:${deg}deg" aria-hidden="true"></span><strong>${safe(value)}</strong></span>`}
function payoutPageButtons(totalPages){if(totalPages<=1)return [1];if(totalPages<=5)return Array.from({length:totalPages},(_,i)=>i+1);if(payoutPage<=2)return [1,2,'…',totalPages];if(payoutPage>=totalPages-1)return [1,'…',totalPages-1,totalPages];return [1,'…',payoutPage-1,payoutPage,payoutPage+1,'…',totalPages]}
function payoutSupportSections(){return `<section class="payout-share"><span class="payout-share-mark" aria-hidden="true">↗</span><h2>Want to share your payout data?</h2><p>Use the Help Center to send Prop Firm Lenz a public transaction reference or source we can review. Submissions are checked before they can appear in the tracker.</p></section><section class="additional-info payout-additional"><div class="review-info-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 5.5c2.8-.8 5.2-.2 8 1.6 2.8-1.8 5.2-2.4 8-1.6v13c-2.8-.8-5.2-.2-8 1.6-2.8-1.8-5.2-2.4-8-1.6v-13Z"/><path d="M12 7.1v13"/></svg></div><div><h2>Additional Information</h2><p>Prop Firm Lenz’s goal is transparent comparison. These are tracked payout records, not totals submitted by firms, and they should be used alongside current firm rules and verified reviews.</p><p>Figures update automatically and may not represent firms’ full payout volume.</p></div></section><section class="payout-faq-wrap"><h2>Frequently Asked Questions (FAQ)</h2><div class="payout-faq-list">${payoutFaqs.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div><a class="payout-help-btn" href="#footer">Help Center</a></section>`}
const payoutFaqs=[
['What is the Prop Firm Payouts Tracker?','It compares tracked blockchain-verified payout records across prop firms, including totals, payout counts, and available firm-level metrics.'],
['Can I compare payout processing time across prop firms?','Yes when the dataset includes a median processing time. If that metric is unavailable, the table shows an em dash rather than an estimate.'],
['Does this page show payout rules or payout requirements?','No. It tracks recorded payouts. Check each firm’s current rules for eligibility, minimum amounts, schedules, and review requirements.'],
['How often is the Payouts Tracker updated?','The embedded payout dataset refreshes automatically every 1 minute. The timestamp above the tracker shows the snapshot used by this page.'],
['What does “median payout time” mean?','The median is the middle processing time after all recorded payout times are ordered. It is less affected by unusually fast or slow payouts than an average.'],
['Why show both “average payout size” and “largest single payout”?','Average payout size describes a typical recorded amount, while the largest payout shows the highest single tracked record in the selected timeframe.'],
['How do I compare recent payouts vs long-term payout history?','Use the timeframe selector and compare only periods that provide firm-level rows. If a period has aggregate data but no firm breakdown, the tracker says so.'],
['How do I keep comparisons consistent across firms?','Use the same timeframe and category, then compare payout counts, totals, and available size metrics together.'],
['Do higher payout totals mean a firm is better?','Not necessarily. Totals can reflect scale and activity. They do not by themselves measure rules, risk, reliability, or trader experience.'],
['Are payout delays always a red flag?','No. Processing times can depend on the payout method, review steps, weekends, and firm rules. Look for a consistent pattern and verify the current terms.']];
function payoutTrackerTabs(){return `<div class="payout-primary-tabs" role="tablist" aria-label="Payout tracker views"><button class="${payoutMode==='payouts'?'on':''}" type="button" data-payout-mode="payouts">Payouts</button><button class="${payoutMode==='leaderboard'?'on':''}" type="button" data-payout-mode="leaderboard">Trader Leaderboard</button></div>`}
function renderPayoutLeaderboard(){const rows=(PAYOUT_DATA.trader_leaderboard||PAYOUT_DATA.traderLeaderboard||PAYOUT_DATA.leaderboard||[]).filter(x=>!x.firm||firmInMarket(payoutCanonicalName(x.firm)));const content=Array.isArray(rows)&&rows.length?`<div class="payout-table">${rows.map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Trader">${safe(x.trader??x.name)}</strong><span data-label="Firm">${safe(x.firm)}</span><span data-label="Amount">${safe(x.amount)}</span><span data-label="Date">${safe(x.date)}</span></div>`).join('')}</div>`:'<div class="payout-leaderboard-empty">Trader-level payout data isn’t available in our dataset yet</div>';document.querySelector('#payoutView').innerHTML=payoutTrackerTabs()+content+payoutSupportSections();bindPayoutForm()}
function renderPayouts(){let all=payoutRowsForTimeframe().filter(r=>firmInMarket(payoutCanonicalName(r.firm)));const categoryCount=all.length;let rows=all.filter(r=>payoutCanonicalName(r.firm).toLowerCase().includes(payoutQuery));rows=sortPayoutRows(rows);const pageSize=10,totalPages=Math.max(1,Math.ceil(rows.length/pageSize));payoutPage=Math.min(payoutPage,totalPages);const pageRows=rows.slice((payoutPage-1)*pageSize,payoutPage*pageSize);const maxTotal=Math.max(1,...rows.map(r=>moneyNumber(r.total))),maxAverage=Math.max(1,...rows.map(r=>moneyNumber(r.average)));const labels={latest_24h:'Last 24 Hours',weekly:'Week To Date',monthly:'Month To Date',last_30d:'Last 30 Days',all_time:'All Time'};const controls=`<div class="payout-controls"><select class="payout-select" id="payoutTimeframe" aria-label="Payout timeframe">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${payoutTimeframe===k?'selected':''}>${v}</option>`).join('')}</select><div class="payout-categories" aria-label="Firm category"><span class="payout-category on">${marketLabel()} <b>${categoryCount}</b></span></div><button class="payout-method-pill" type="button" data-payout-methodology><span>◇</span>How We Verify and Rank Firms</button><label class="payout-search-wrap"><span aria-hidden="true">⌕</span><input class="payout-search" id="payoutSearch" type="search" value="${safe(payoutQuery)}" placeholder="Search" aria-label="Search firms by name"></label></div>`;const head=`<div class="payout-tracker-head"><div class="payout-firm-sorts"><button class="${payoutSort==='firm'?'on':''}" type="button" data-payout-sort="firm">A–Z</button><i></i><button class="${payoutSort==='rank'?'on':''}" type="button" data-payout-sort="rank">Rank</button><i></i><button class="${payoutSort==='reviews'?'on':''}" type="button" data-payout-sort="reviews">Reviews</button></div><button class="${payoutSort==='total'?'on':''}" type="button" data-payout-sort="total">Total Payouts</button><button class="${payoutSort==='count'?'on':''}" type="button" data-payout-sort="count">Amount of Payouts</button><button class="${payoutSort==='largest'?'on':''}" type="button" data-payout-sort="largest">Largest Single Payout</button><button class="${payoutSort==='average'?'on':''}" type="button" data-payout-sort="average">Average Payout Size</button><button class="${payoutSort==='median'?'on':''}" type="button" data-payout-sort="median">Median Time</button><span>Actions</span></div>`;const body=pageRows.length?pageRows.map(r=>{const total=moneyNumber(r.total),width=total?Math.max(2,total/maxTotal*100):0;return `<article class="payout-tracker-row">${payoutFirm(r.firm)}<div class="payout-total-cell" data-label="Total payouts"><strong>${safe(r.total)}</strong><span class="payout-total-track"><i style="width:${width}%"></i></span></div><span class="payout-number" data-label="Amount of payouts">${safe(r.count)}</span><span class="payout-number" data-label="Largest single payout">${safe(r.largest)}</span><div data-label="Average payout size">${payoutGauge(r.average,maxAverage)}</div><div data-label="Median time">${payoutSpeed(r)}</div><button class="payout-view-button" type="button" data-payout-detail="${safe(r.firm)}">View</button></article>`}).join(''):`<div class="payout-leaderboard-empty">${payoutTimeframe==='all_time'?'Firm-level all-time records aren’t available in this dataset yet.':'No payout firms match these filters.'}</div>`;const pages=payoutPageButtons(totalPages);const pagination=rows.length?`<nav class="payout-pagination" aria-label="Payout pages"><button class="page-word" type="button" data-payout-nav="prev" ${payoutPage===1?'disabled':''}>Previous</button>${pages.map(x=>x==='…'?'<span aria-hidden="true">…</span>':`<button class="${x===payoutPage?'current':''}" type="button" data-payout-page="${x}" ${x===payoutPage?'aria-current="page"':''}>${x}</button>`).join('')}<button class="page-word" type="button" data-payout-nav="next" ${payoutPage===totalPages?'disabled':''}>Next</button></nav>`:'';document.querySelector('#payoutView').innerHTML=payoutTrackerTabs()+controls+`<div class="payout-tracker-table">${head}${body}</div>`+pagination+payoutSupportSections();const search=document.querySelector('#payoutSearch');search?.addEventListener('input',e=>{payoutQuery=e.target.value.trim().toLowerCase();payoutPage=1;renderPayouts();const next=document.querySelector('#payoutSearch');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)});document.querySelector('#payoutTimeframe')?.addEventListener('change',e=>{payoutTimeframe=e.target.value;payoutCategory='forex';payoutPage=1;renderPayouts()});bindPayoutForm()}
function bindPayoutForm(){document.querySelector('#payoutSubscribeForm')?.addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.checkValidity()){e.currentTarget.reportValidity();return}document.querySelector('#payoutFormNote').textContent='Email validated. Live subscription delivery is not connected in this preview.';showToast('Email validated')})}
function bindHomeForm(){document.querySelector('#subscribe')?.addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.checkValidity()){e.currentTarget.reportValidity();return}const note=e.currentTarget.parentElement?.querySelector('.form-note');if(note)note.textContent='Email validated. Live subscription delivery is not connected in this preview.';showToast('Email validated')})}
function payoutDetailCutoff(){const now=new Date(PAYOUT_DATA.captured_at);const days=payoutDetailTimeframe==='7d'?7:payoutDetailTimeframe==='30d'?30:payoutDetailTimeframe==='365d'?365:null;if(days==null)return null;return new Date(now.getTime()-days*86400000)}
function payoutDetailRecords(){const canonical=payoutCanonicalName(payoutDetailFirm),cutoff=payoutDetailCutoff();return (PAYOUT_DATA.records||[]).filter(x=>payoutCanonicalName(x.firm)===canonical&&(!cutoff||new Date(x.date)>=cutoff)).sort((a,b)=>new Date(b.date)-new Date(a.date))}
function payoutDetailSummary(){const canonical=payoutCanonicalName(payoutDetailFirm);if(payoutDetailTimeframe==='7d'){const row=(PAYOUT_DATA.weekly?.rows||[]).find(x=>payoutCanonicalName(x.firm)===canonical);if(row)return {total:row.cells?.[2]||'—',count:row.cells?.[3]||'—',growth:row.cells?.[4]||'—'}}if(payoutDetailTimeframe==='30d'){const row=(PAYOUT_DATA.stats?.top5_30d||[]).find(x=>payoutCanonicalName(x.firm)===canonical);if(row)return {total:usd(row.usd),count:whole(row.count),growth:'—'}}return {total:'—',count:'—',growth:'—'}}
function payoutDetailPages(total){return total<=5?Array.from({length:total},(_,i)=>i+1):payoutDetailPage<=2?[1,2,'…',total]:payoutDetailPage>=total-1?[1,'…',total-1,total]:[1,'…',payoutDetailPage-1,payoutDetailPage,payoutDetailPage+1,'…',total]}
function renderPayoutDetail(){const host=document.querySelector('#payoutDetailContent');if(!host)return;const canonical=payoutCanonicalName(payoutDetailFirm);if(!canonical){host.innerHTML='<div class="detail-empty">Choose a firm from the payout tracker.</div>';return}const summary=payoutDetailSummary(),records=payoutDetailRecords(),largest=records.reduce((best,x)=>moneyNumber(x.amount)>moneyNumber(best?.amount)?x:best,null),trust=payoutTrustpilot(payoutDetailFirm),pageSize=6,totalPages=Math.max(1,Math.ceil(records.length/pageSize));payoutDetailPage=Math.min(payoutDetailPage,totalPages);const pageRows=records.slice((payoutDetailPage-1)*pageSize,payoutDetailPage*pageSize);const trustMarkup=trust&&trust.trustpilotRating!=null&&trust.trustpilotReviews!=null?`<span class="payout-trustpilot"><b>${trust.trustpilotRating.toFixed(1)}</b><span class="rating-out-of">/ 5</span><span>${Number(trust.trustpilotReviews).toLocaleString()}</span></span>`:'<span class="payout-trustpilot empty">Trustpilot —</span>';const labels={'7d':'Last 7 Days','30d':'Last 30 Days','365d':'Last 365 Days',all:'All Time'};const recent=pageRows.length?pageRows.map(x=>`<div class="recent-payout-row"><span data-label="Date">${safe(x.date)}</span><strong data-label="Payout">${safe(x.amount)}</strong><span data-label="Account size">—</span><span data-label="% of return">—</span><span data-label="Payout waiting time"><span class="wait-badge">—</span></span></div>`).join(''):'<div class="detail-empty">No individual payout records are available for this firm and timeframe.</div>';const pages=payoutDetailPages(totalPages);host.innerHTML=`<div class="payout-detail-identity">${logo(payoutDetailFirm)}<div><h1>${safe(canonical)}</h1>${trustMarkup}</div></div><div class="payout-detail-title-row"><h2>${safe(canonical)} Prop Firm Payouts Details</h2><div class="payout-detail-timeframes">${Object.entries(labels).map(([key,label])=>`<button class="${payoutDetailTimeframe===key?'on':''}" type="button" data-detail-timeframe="${key}">${label}</button>`).join('')}</div><button class="delay-report-btn" type="button" data-delay-report>△ Report a delayed payout</button></div><div class="detail-stat-grid"><article class="detail-stat"><span>Total Payouts</span><strong>${safe(summary.total)}</strong></article><article class="detail-stat"><span>Number of Payouts</span><strong>${safe(summary.count)}</strong></article><article class="detail-stat"><span>Largest Single Payout</span><strong>${largest?safe(largest.amount):'—'}</strong></article><article class="detail-stat"><span>Payout Growth</span><strong>${safe(summary.growth)}</strong></article><article class="detail-stat"><span>Median Time</span><strong>—</strong><span class="detail-stat-note"><span class="detail-speed">Not tracked</span></span></article><article class="detail-stat"><span>Reported Delays</span><strong>—</strong></article></div><section class="detail-chart-card"><div class="detail-card-head"><h3>Total Payouts</h3><span class="powered-lenz">Powered by <img src="assets/logo.png" alt=""><b>Prop Firm Lenz</b></span></div><div class="detail-chart-empty">Monthly firm-level totals and a cumulative series aren’t available in the embedded payout dataset.</div></section><div class="detail-bottom-grid"><section class="detail-table-card"><h3>Recent Payouts</h3><div class="recent-payout-head"><span>Date</span><span>Payout</span><span>Account Size</span><span>% of Return</span><span>Payout Waiting Time</span></div>${recent}${records.length?`<nav class="detail-pagination" aria-label="Recent payout pages"><button type="button" data-detail-nav="prev" ${payoutDetailPage===1?'disabled':''}>Previous</button>${pages.map(x=>x==='…'?'<span>…</span>':`<button class="${x===payoutDetailPage?'current':''}" type="button" data-detail-page="${x}">${x}</button>`).join('')}<button type="button" data-detail-nav="next" ${payoutDetailPage===totalPages?'disabled':''}>Next</button></nav>`:''}</section><section class="detail-region-card"><h3>Payouts Per Region</h3><div class="region-empty-ring"><span><b>—</b>Total Payouts</span></div><div class="region-list"><div><span>Region data</span><strong>—</strong></div><p>Region breakdowns aren’t included in the embedded payout dataset.</p></div></section></div>`}
function openPayoutFirmDetail(name){payoutDetailFirm=name;payoutDetailTimeframe='7d';payoutDetailPage=1;renderPayoutDetail();openPage('payout-detail')}
function statCard(label,value,detail){return `<article class="payout-stat-card"><span class="label">${label}</span><strong class="value">${value}</strong><p>${detail}</p></article>`}
function simpleStatsTable(title,headers,rows,cols=4){return `<div class="payout-block"><h3>${title}</h3><div class="payout-table"><div class="payout-row header" data-cols="${cols}">${headers.map(x=>`<span>${x}</span>`).join('')}</div>${rows.join('')}</div></div>`}
function renderStatistics(){const day=(PAYOUT_DATA.latest_24h||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))),week=(PAYOUT_DATA.weekly?.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))),month=(PAYOUT_DATA.monthly?.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));const sum=(rows,get)=>rows.reduce((total,x)=>total+moneyNumber(get(x)),0);const leader=(rows,get)=>rows.length?[...rows].sort((a,b)=>moneyNumber(get(b))-moneyNumber(get(a)))[0].firm:'—';const forexCards=[statCard('Last 24 hours',usd(sum(day,x=>x.total)),`${whole(sum(day,x=>x.count))} payouts · ${day.length} ${marketLabel()} firms · led by ${safe(leader(day,x=>x.total))}`),statCard('Week to date',usd(sum(week,x=>x.cells?.[2])),`${whole(sum(week,x=>x.cells?.[3]))} payouts · ${week.length} ${marketLabel()} firms · led by ${safe(leader(week,x=>x.cells?.[2]))}`),statCard('Month to date',usd(sum(month,x=>x.cells?.[2])),`${whole(sum(month,x=>x.cells?.[3]))} payouts · ${month.length} ${marketLabel()} firms · led by ${safe(leader(month,x=>x.cells?.[2]))}`)];const forexTop=(PAYOUT_DATA.stats?.top5_30d||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));document.querySelector('#payoutView').innerHTML=`<div class="payout-card-grid">${forexCards.join('')}</div><div class="payout-block" style="margin-top:14px"><h3>${marketLabel()} firms · last 30 days</h3>${forexTop.length?`<div class="progress-list">${forexTop.map(x=>`<div><div class="progress-top"><b>${safe(payoutCanonicalName(x.firm))}</b><span>${usd(x.usd)} · ${whole(x.count)} payouts</span></div><span class="progress-track"><i style="width:${Math.min(100,x.share||0)}%"></i></span></div>`).join('')}</div>`:'<div class="payout-leaderboard-empty">${marketLabel()} 30-day firm totals aren’t available in this dataset yet.</div>'}</div><div class="payout-leaderboard-empty">Long-term aggregate statistics are not shown because the embedded dataset does not separate them by market category.</div>`;return;const s=PAYOUT_DATA.stats,m=s.by_month||[],max=Math.max(...m.map(x=>x.usd),1);const cards=[statCard('Last 24 hours',usd(s.last_24h.usd),`${whole(s.last_24h.count)} payouts · ${s.last_24h.firms} firms · led by ${safe(s.last_24h.leading_firm)}`),statCard('Week to date',usd(s.week_to_date.usd),`${whole(s.week_to_date.count)} payouts · ${s.week_to_date.firms} firms · led by ${safe(s.week_to_date.leading_firm)}`),statCard('Month to date',usd(s.month_to_date.usd),`${whole(s.month_to_date.count)} payouts · ${s.month_to_date.firms} firms · led by ${safe(s.month_to_date.leading_firm)}`),statCard('Last 30 days',usd(s.last_30d.usd),`${whole(s.last_30d.count)} payouts · avg ${usd(s.last_30d.avg)} · median ${usd(s.last_30d.median)} · ${pct(s.last_30d.vs_prior_30d_pct)} vs prior`),statCard('All time',usd(s.all_time.usd),`${whole(s.all_time.count)} payouts · ${s.all_time.firms} firms · since ${safe(s.all_time.since)}`),statCard('Largest single payout',usd(s.largest_on_record.usd),`${safe(s.largest_on_record.firm)} · ${safe(s.largest_on_record.date)}`)];const top=(s.top5_30d||[]).map(x=>`<div><div class="progress-top"><b>${safe(x.firm)}</b><span>${usd(x.usd)} · ${whole(x.count)} payouts · ${x.share}%</span></div><span class="progress-track"><i style="width:${Math.min(100,x.share)}%"></i></span></div>`).join('');const sizes=(s.size_buckets_30d||[]).map(x=>`<div class="payout-row" data-cols="5"><strong data-label="Size">${safe(x.bucket)}</strong><span data-label="Payouts">${whole(x.count)}</span><span data-label="Share">${x.share_of_payouts_pct}%</span><strong data-label="USD" class="payout-money">${usd(x.usd)}</strong><span data-label="USD share">${x.share_of_usd_pct}%</span></div>`).join('');const q=(s.by_quarter||[]).slice(-8).reverse().map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Quarter">${safe(x.quarter)}${x.in_progress?' · in progress':''}</strong><span data-label="USD">${usd(x.usd)}</span><span data-label="Payouts">${whole(x.count)}</span><span data-label="Firms">${x.firms}</span></div>`);const y=(s.by_year||[]).map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Period">${safe(x.label)}</strong><span data-label="USD">${usd(x.usd)}</span><span data-label="Payouts">${whole(x.count)}</span><span data-label="Firms">${x.firms}</span></div>`);document.querySelector('#payoutView').innerHTML=`<div class="payout-card-grid">${cards.join('')}</div><div class="payout-split"><div class="payout-block"><h3>Top 5 firms · last 30 days</h3><div class="progress-list">${top}</div></div><div class="payout-block"><h3>Payout sizes · last 30 days</h3><div class="payout-table payout-size-table"><div class="payout-row header" data-cols="5"><span>Size</span><span>Payouts</span><span>Share</span><span>USD</span><span>USD share</span></div>${sizes}</div></div></div><div class="payout-split">${simpleStatsTable('By quarter · newest first',['Quarter','USD','Payouts','Firms'],q)}${simpleStatsTable('By year',['Period','USD','Payouts','Firms'],y)}</div><div class="payout-block" style="margin-top:14px"><h3>12-month verified payout volume</h3><div class="month-chart">${m.map(x=>`<div class="month-col" title="${safe(x.month)}: ${usd(x.usd)}"><b>${usd(x.usd)}</b><i style="height:${Math.max(4,x.usd/max*100)}%"></i><span>${safe(x.month.slice(5))}</span></div>`).join('')}</div></div>`}
function renderPeriod(kind){const d=PAYOUT_DATA[kind];const forexRows=(d.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));const forexTotal=Math.max(1,forexRows.reduce((sum,x)=>sum+moneyNumber(x.cells?.[2]),0));const rows=forexRows.map(x=>{const c=x.cells;const change=String(c[4]).includes('▲')?'payout-positive':'payout-negative';return `<div class="payout-row" data-cols="7"><strong data-label="#">${safe(c[0])}</strong>${payoutFirm(x.firm)}<span data-label="Method" class="payout-muted">${safe(x.method)}</span><strong data-label="Total" class="payout-money">${safe(c[2])}</strong><span data-label="Payouts">${safe(c[3])}</span><span data-label="WoW" class="${change}">${safe(c[4])}</span><span data-label="Share">${(moneyNumber(c[2])/forexTotal*100).toFixed(1)}%</span></div>`}).join('');document.querySelector('#payoutView').innerHTML=`<div class="payout-headline"><div><span>${kind==='weekly'?'Verified weekly total':'Verified monthly total'}</span><strong>${usd(forexRows.reduce((sum,x)=>sum+moneyNumber(x.cells?.[2]),0))}</strong></div><b>${safe(d.headline.range)}</b></div><div class="payout-table"><div class="payout-row header" data-cols="7"><span>#</span><span>Firm</span><span>Tracked method</span><span>Total</span><span>Payouts</span><span>WoW</span><span>Share</span></div>${rows||`<div class="payout-leaderboard-empty">No verified ${marketLabel()} payout rows are available for this period.</div>`}</div><div class="payout-caption"><span>${kind==='weekly'?"WoW compares with the prior week's full total.":"MoM compares with the prior month's full total."}</span></div>`}
function renderRecords(){const rows=(PAYOUT_DATA.records||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))).map((x,i)=>`<div class="payout-row" data-cols="5"><strong data-label="#">${i+1}</strong>${payoutFirm(x.firm)}<span data-label="Method" class="payout-muted">${safe(x.method)}</span><span data-label="Date">${safe(x.date)}</span><strong data-label="Amount" class="payout-money">${safe(x.amount)}</strong></div>`).join('');document.querySelector('#payoutView').innerHTML=`<div class="payout-headline"><div><span>Records</span><strong>Largest verified single payouts</strong></div></div><div class="payout-table"><div class="payout-row header" data-cols="5"><span>#</span><span>Firm</span><span>Method</span><span>Date</span><span>Amount</span></div>${rows||`<div class="payout-leaderboard-empty">No verified ${marketLabel()} payout records are available.</div>`}</div>`}
function renderMethodology(){document.querySelector('#payoutView').innerHTML=`<div class="payout-copy"><h3>What blockchain-verified means</h3><p>A payout is verified when its settlement can be tied to a real transaction recorded on a public blockchain. That creates an independently inspectable trail rather than relying only on a firm's announcement.</p><div class="verify-steps"><article class="verify-step"><b>01 · Find wallets</b><p>Identify payout wallets associated with each tracked firm and method.</p></article><article class="verify-step"><b>02 · Locate the transaction</b><p>Match a settlement to its transaction hash on the relevant chain.</p></article><article class="verify-step"><b>03 · Check the token</b><p>Confirm the transferred asset against the correct token contract.</p></article><article class="verify-step"><b>04 · Record settlement</b><p>Capture the verified amount and the time the transfer settled.</p></article></div><h3>What is not counted</h3><p>Firm-reported totals alone are excluded. Payouts sent by bank transfer, payment card, or any other rail that cannot be tracked on-chain are also outside this dataset.</p><h3>Questions about verification</h3><div class="payout-faq"><details><summary>What counts as verified?</summary><p>A settlement with a traceable transaction hash, confirmed token contract, amount, and timestamp on a public blockchain.</p></details><details><summary>Does this cover every payout?</summary><p>No. It covers only tracked blockchain payments and may not represent a firm's full payout activity.</p></details><details><summary>How often does it update?</summary><p>The embedded payout snapshot refreshes on a 1-minute schedule.</p></details><details><summary>Can I verify a payout myself?</summary><p>Yes. A transaction hash can be checked with any public explorer that supports the relevant blockchain.</p></details><details><summary>Are listed firms endorsed?</summary><p>No. Inclusion is a record of tracked activity, not an endorsement or recommendation.</p></details></div></div>`}
function renderAbout(){document.querySelector('#payoutView').innerHTML=`<div class="payout-copy"><h3>How this payout hub works</h3><div class="about-steps"><article class="verify-step"><b>Track</b><p>Monitor supported on-chain payout methods across listed firms.</p></article><article class="verify-step"><b>Verify</b><p>Check transactions and token contracts against public blockchain records.</p></article><article class="verify-step"><b>Publish</b><p>Present totals, trends, and records in a comparable format.</p></article><article class="verify-step"><b>Exclude</b><p>Leave out claims and payment rails that cannot be independently tracked.</p></article></div><h3>Independent by design</h3><p>Paid placement does not influence the payout tables. A listing documents tracked settlements; it is not an endorsement of a firm, product, or offer.</p><h3>Using the data</h3><p>Figures update automatically and may not represent firms’ full payout volume. Use them alongside current firm rules and verified reviews.</p><span class="contact-placeholder">Contact us</span></div>`}
function renderPayoutView(){document.querySelectorAll('[data-payout-view]').forEach(b=>b.classList.toggle('on',b.dataset.payoutView===payoutView));if(!payoutHeader()){payoutEmpty();return}if(payoutView==='payouts'){if(payoutMode==='leaderboard')renderPayoutLeaderboard();else renderPayouts()}else if(payoutView==='statistics')renderStatistics();else if(payoutView==='weekly'||payoutView==='monthly')renderPeriod(payoutView);else if(payoutView==='records')renderRecords();else if(payoutView==='methodology')renderMethodology();else renderAbout()}

let compareSelections=['FundedNext','FundingPips','Alpha Capital',''];
function compareChallenge(name){return CHALLENGES_DATA.filter(x=>x.firm===name&&x.account_size==='100K'&&x.steps==='2 Steps').sort((a,b)=>Number(a.price)-Number(b.price)||Number(b.popularity)-Number(a.popularity))[0]||null}
function comparePayout(name,kind){const source=kind==='latest'?(PAYOUT_DATA.latest_24h||[]):(PAYOUT_DATA.monthly?.rows||[]);const row=source.find(x=>payoutCanonicalName(x.firm)===name);if(!row)return '—';return kind==='latest'?(row.total||'—'):(row.cells?.[2]||'—')}
function compareCell(value,detail=''){return `<div class="compare-value"><b>${value==null||value===''?'—':safe(value)}</b>${detail?`<span>${safe(detail)}</span>`:''}</div>`}
function renderCompare(){const marketFirms=sourceFirms(),choices=marketFirms.map(f=>f.name).sort((a,b)=>a.localeCompare(b));document.querySelector('#compareFirmCount').textContent=choices.length;document.querySelector('#compareChallengeCount').textContent=CHALLENGES_DATA.filter(x=>firmInMarket(x.firm)).length;const picker=document.querySelector('#comparePicker');picker.innerHTML=compareSelections.map((selected,index)=>`<label>Firm ${index+1}<select data-compare-slot="${index}"><option value="">Add a firm</option>${choices.map(name=>`<option value="${safe(name)}" ${name===selected?'selected':''} ${compareSelections.includes(name)&&name!==selected?'disabled':''}>${safe(name)}</option>`).join('')}</select></label>`).join('');const selected=compareSelections.filter(Boolean);const table=document.querySelector('#compareTable');if(!selected.length){table.innerHTML=`<div class="compare-empty">Choose at least one ${marketLabel()} firm to begin the comparison.</div>`;return}const head=`<div class="compare-row"><div class="compare-label">Firm</div>${selected.map(name=>`<div class="compare-firm-head">${logo(name)}<div><strong>${safe(name)}</strong><span class="rating">${marketLabel()} comparison</span></div></div>`).join('')}</div>`;const rows=[['Trustpilot rating',name=>{const f=TRUSTPILOT_FIRMS.find(x=>x.name===name);return compareCell(f?.trustpilotRating==null?'—':`${f.trustpilotRating.toFixed(1)} / 5`,f?.trustpilotReviews==null?'—':`${Number(f.trustpilotReviews).toLocaleString()} reviews`)}],['Challenge price',name=>{const x=compareChallenge(name);return compareCell(x?challengeMoney(x,x.price):'—',x?'Lowest tracked 100K · 2 Steps':'Not tracked yet')}],['Profit target',name=>{const x=compareChallenge(name);return compareCell(x?.profit_target||'—')}],['Daily / max loss',name=>{const x=compareChallenge(name);return compareCell(x?`${x.daily_loss||'—'} / ${x.max_loss||'—'}`:'—',x?.max_loss_type||'Not tracked yet')}],['Profit split',name=>{const x=compareChallenge(name);return compareCell(x?.profit_split||'—')}],['Payout frequency',name=>{const x=compareChallenge(name);return compareCell(x?.payout_freq||'—')}],['Platforms',name=>{const f=marketFirms.find(x=>x.name===name);return compareCell(f?.platforms?.join(', ')||'—')}],['LENZ offer',name=>{const x=OFFER_CATALOG.find(o=>o.name===name);return x?`<div class="compare-value"><b>${safe(x.discount)}</b><span class="compare-code">LENZ</span></div>`:compareCell('—','Not tracked yet')}],['Latest 24h payouts',name=>compareCell(comparePayout(name,'latest'))],['Month-to-date payouts',name=>compareCell(comparePayout(name,'monthly'))]];table.style.setProperty('--compare-cols',selected.length);table.innerHTML=head+rows.map(([label,fn])=>`<div class="compare-row"><div class="compare-label">${label}</div>${selected.map(name=>fn(name)).join('')}</div>`).join('')}
function renderSpreads(){const q=(document.querySelector('#spreadsSearch')?.value||'').trim().toLowerCase();const rows=sourceFirms().filter(f=>f.name.toLowerCase().includes(q));document.querySelector('#spreadsCount').textContent=rows.length;document.querySelector('#spreadsRows').innerHTML=rows.length?rows.map(f=>{const t=TRUSTPILOT_FIRMS.find(x=>x.name===f.name),score=t?.trustpilotRating,offer=OFFER_CATALOG.find(x=>x.name===f.name),visit=offer?.buyLink?`<a class="spread-visit" href="${safe(offer.buyLink)}" target="_blank" rel="noopener noreferrer">Visit</a>`:'<span class="spread-visit disabled" aria-label="Official link not available">—</span>',missing='<span class="spread-missing" title="Not tracked yet" aria-label="Not tracked yet">—</span>';return `<article class="spread-row"><span class="spread-rank" data-label="Rank">${f.rank}</span><div class="spread-firm" data-label="Firm">${logo(f.name)}<div><strong>${safe(f.name)}</strong><span class="rating">${marketLabel()}</span></div></div><span data-label="Avg. spread">${missing}</span><span data-label="EUR/USD">${missing}</span><span data-label="GBP/USD">${missing}</span><span data-label="USD/JPY">${missing}</span><span data-label="XAU/USD">${missing}</span><span data-label="US30">${missing}</span><span data-label="NAS100">${missing}</span><span class="spread-platforms" data-label="Platforms">${f.platforms.map(platformIcon).join('')||missing}</span><span class="spread-trust" data-label="Trustpilot">${score==null?'—':`${score.toFixed(1)}<span class="rating-out-of">/ 5</span>`}</span><span data-label="Visit">${visit}</span></article>`}).join(''):`<div class="spreads-empty">No ${marketLabel()} firms match your search.</div>`}

const PAGE_NAMES=new Set(['home','offers','challenges','best-sellers','reviews','favorites','rules','compare','spreads','payouts','payout-detail','tutorials','firm-profile']);
const PAGE_TARGETS={home:'#home',offers:'#offersPage',challenges:'#challengesPage','best-sellers':'#rankings',reviews:'#home',favorites:'#favoritesPage',rules:'#resources',compare:'#comparePage',spreads:'#spreadsPage',payouts:'#payouts','payout-detail':'#payoutDetailPage',tutorials:'#videos','firm-profile':'#firmProfilePage'};
const LEGACY_ROUTES={home:'home',offers:'offers',rankings:'compare',faq:'reviews',resources:'rules',payouts:'payouts',videos:'tutorials',futures:'offers'};
let currentPage='home',routeHistoryIndex=Number(history.state?.pflRouteIndex)||0;
function configurePage(page){
  const reviewPage=page==='reviews',label=marketLabel(),categoryFirms=categoryTrustpilotFirms(),categoryChallenges=CHALLENGES_DATA.filter(x=>firmInMarket(x.firm)),reviewVolume=categoryFirms.reduce((sum,f)=>sum+(Number(f.trustpilotReviews)||0),0),payoutFirmCount=new Set([...(PAYOUT_DATA.latest_24h||[]),...(PAYOUT_DATA.weekly?.rows||[]),...(PAYOUT_DATA.monthly?.rows||[])].filter(x=>firmInMarket(payoutCanonicalName(x.firm))).map(x=>payoutCanonicalName(x.firm))).size;
  updateMarketCopy();
  document.querySelector('#heroTitle').textContent=`Compare the Best ${label} Prop Trading Firms of 2026`;
  document.querySelector('#heroSubtitle').textContent=reviewPage?`Compare ${label} prop firms using real Trustpilot reviews and PFL community reviews.`:`Trusted platform to compare ${label} prop trading firms using verified data and insights, including reviews, rules, and rankings.`;
  document.querySelector('#heroFirmCount').textContent=categoryFirms.length.toLocaleString();
  document.querySelector('#heroFirmLabel').textContent=reviewPage?'Verified Prop Firms':'Firms Covered';
  document.querySelector('#heroChallengeCount').textContent=categoryChallenges.length.toLocaleString();
  document.querySelector('#heroChallengeLabel').textContent=reviewPage?'Tracked Challenges':`${label} Challenges`;
  document.querySelector('#heroOfferCount').textContent=reviewPage?reviewVolume.toLocaleString():forexOffers().length.toLocaleString();
  document.querySelector('#heroOfferLabel').textContent=reviewPage?'Trustpilot Reviews':'Tracked Offers';
  document.querySelector('#heroPayoutFirmCount').textContent=payoutFirmCount.toLocaleString();
  document.querySelector('#heroPayoutLabel').textContent=reviewPage?'Payout Firms':'Payout Firms';
  if(page==='challenges'){challengePage=1;renderChallenges()}
  else if(page==='best-sellers'){view='firms';currentFilter='popular';sortKey='favorites';sortDir='desc'}
  else if(page==='reviews'){reviewMinimum=0;reviewSource='trustpilot';document.querySelector('#reviewAmount').value='0';document.querySelector('#reviewAmountValue').textContent='0+';renderReviews()}
  else if(page==='favorites'){favoriteQuery='';document.querySelector('#favoriteSearch').value='';renderFavoriteFirms()}
  else if(page==='compare'){renderCompare()}
  else if(page==='spreads'){renderSpreads()}
  document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('on',b.dataset.filter===currentFilter));
  if(page==='best-sellers')renderMain();
  if(page==='payouts'){payoutView='payouts';payoutMode='payouts';payoutQuery='';payoutCategory=market;payoutPage=1;renderPayoutView()}
  if(page==='payout-detail')renderPayoutDetail()
  if(page==='firm-profile'){const name=profileNameFromSlug(currentProfileSlug);if(name)renderFirmProfile(name)}
}
function openPage(page,{replace=false,scroll=true,configure=true}={}){
  if(!PAGE_NAMES.has(page))page='home';
  if(page==='firm-profile'&&!profileNameFromSlug(currentProfileSlug))page='home';
  if(page!=='firm-profile')profileScrollSpyCleanup();
  currentPage=page;
  if(configure)configurePage(page);
  document.querySelectorAll('[data-page-panel]').forEach(panel=>{panel.hidden=!panel.dataset.pagePanel.split(/\s+/).includes(page)});
  const marketEmpty=document.querySelector('#marketEmpty');marketEmpty.hidden=true;
  document.querySelectorAll('.navlinks [data-page]').forEach(link=>{const active=link.dataset.page===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});
  renderFaqForPage(page);
  const hash=page==='firm-profile'?`#firm/${currentProfileSlug}`:`#page-${page}`;
  try{if(replace){const stateIndex=Number(history.state?.pflRouteIndex);if(Number.isFinite(stateIndex))routeHistoryIndex=stateIndex;history.replaceState({pflRoute:true,pflRouteIndex:routeHistoryIndex,pflPage:page,...(page==='firm-profile'?{pflProfileOrigin:profileOriginHash||'#page-home'}:{})},'',hash)}else if(location.hash!==hash){routeHistoryIndex+=1;history.pushState({pflRoute:true,pflRouteIndex:routeHistoryIndex,pflPage:page,...(page==='firm-profile'?{pflProfileOrigin:profileOriginHash||'#page-home'}:{})},'',hash)}}catch(_){location.hash=hash}
  if(scroll){const target=document.querySelector(PAGE_TARGETS[page]);requestAnimationFrame(()=>{if(!target)return;const header=document.querySelector('.site-head');const top=target.getBoundingClientRect().top+window.scrollY-(header?.offsetHeight||0)-14;window.scrollTo({top:Math.max(0,top),behavior:'smooth'})})}
}
function pageFromHash(){const raw=location.hash.slice(1);if(raw.startsWith('firm/')){currentProfileSlug=raw.slice(5);profileOriginHash=history.state?.pflProfileOrigin||'#page-home';return 'firm-profile'}if(raw.startsWith('page-'))return raw.slice(5);return LEGACY_ROUTES[raw]||'home'}
function routeFromHash(){openPage(pageFromHash(),{replace:true,scroll:false})}
const mobileHeaderQuery=window.matchMedia('(max-width: 760px)');
function syncHeaderMenu(){const nav=document.querySelector('#headerMenu'),button=document.querySelector('.menu'),mobile=mobileHeaderQuery.matches;nav.hidden=mobile;button.setAttribute('aria-expanded',String(!mobile));button.setAttribute('aria-label',mobile?'Open navigation menu':'Close navigation menu')}
mobileHeaderQuery.addEventListener?.('change',syncHeaderMenu);syncHeaderMenu();

function openModal(id){document.querySelector(id).classList.add('open');document.querySelector(id+' .modal-close').focus()}
function closeModals(){document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'))}
function renderFaqForPage(page){const list=page==='reviews'?reviewFaqs:page==='favorites'?favoriteFaqs:faqs,label=marketLabel();document.querySelector('#faqTitle').textContent=page==='favorites'||page==='reviews'?'Frequently Asked Questions (FAQ)':page==='offers'?`Offers FAQ (${label})`:`Homepage FAQ (${label})`;document.querySelector('#faqList').innerHTML=list.map(f=>`<details><summary>${f[0].replaceAll('Forex',label)}</summary><p>${f[1].replaceAll('Forex',label)}</p></details>`).join('')}
renderFaqForPage('home');
document.addEventListener('click',e=>{const profileName=e.target.closest('[data-firm-profile]');if(profileName){e.preventDefault();e.stopPropagation();openFirmProfile(profileName.dataset.firmProfile);return}const profileBack=e.target.closest('[data-profile-back]');if(profileBack){const appHistoryIndex=Number(history.state?.pflRouteIndex);if(Number.isFinite(appHistoryIndex)&&appHistoryIndex>0)history.back();else{const targetHash=(history.state?.pflProfileOrigin||profileOriginHash||'#page-home').replace(/^#/,'');const targetPage=targetHash.startsWith('page-')?targetHash.slice(5):(LEGACY_ROUTES[targetHash]||'home');openPage(PAGE_NAMES.has(targetPage)&&targetPage!=='firm-profile'?targetPage:'home',{replace:true})}return}const profileNotice=e.target.closest('[data-profile-notice]');if(profileNotice){const firmObj=profileFirmFor(currentProfileSlug);const firmName=firmObj?.name;if(profileNotice.dataset.profileNotice==='Favorites'&&firmName){if(favorites.has(firmName)){favorites.delete(firmName);showToast(`${firmName} removed from favorites`)}else{favorites.add(firmName);showToast(`${firmName} added to favorites`)}renderFavoriteFirms();renderMain();return}if(profileNotice.dataset.profileNotice==='Reviews'&&firmName){const targetElem=document.querySelector('#pflReviewNoticeFirm');if(targetElem)targetElem.textContent=firmName;openModal('#pflReviewNoticeModal');return}showToast(`${profileNotice.dataset.profileNotice} updated`);return}const profileTabButton=e.target.closest('[data-profile-tab]');if(profileTabButton){scrollToProfileSection(profileTabButton.dataset.profileTab);return}const profileBuy=e.target.closest('[data-profile-buy]');if(profileBuy&&!profileBuy.disabled){const buyLink=profileBuy.dataset.buyLink.trim();if(buyLink){const opened=window.open(buyLink,'_blank','noopener,noreferrer');if(opened)opened.opener=null}return}const menuButton=e.target.closest('.menu');if(menuButton){const nav=document.querySelector('#headerMenu'),opening=nav.hidden;nav.hidden=!opening;menuButton.setAttribute('aria-expanded',String(opening));menuButton.setAttribute('aria-label',opening?'Close navigation menu':'Open navigation menu');return}if(e.target.closest('[data-account-notice]')){openModal('#accountNoticeModal');return}const videoPlay=e.target.closest('[data-video-play]');if(videoPlay){playVideo(videoPlay);return}const pageLink=e.target.closest('[data-page]');if(pageLink){e.preventDefault();if(pageLink.hasAttribute('data-close-modal'))closeModals();openPage(pageLink.dataset.page);return}const reviewSourceButton=e.target.closest('[data-review-source]');if(reviewSourceButton){reviewSource=reviewSourceButton.dataset.reviewSource;renderReviews();return}const pflWriteButton=e.target.closest('[data-write-pfl-review]');if(pflWriteButton){openPflReviewNotice(pflWriteButton.dataset.writePflReview);return}if(e.target.closest('[data-post-review]')){reviewSource='pfl';renderReviews();document.querySelector('#pflReviewsPanel').scrollIntoView({behavior:'smooth',block:'start'});return}const reviewMethod=e.target.closest('[data-review-methodology]');if(reviewMethod){openModal('#reviewMethodModal');return}const reviewViewButton=e.target.closest('[data-view-reviews]');if(reviewViewButton){openFirmReviews(reviewViewButton.dataset.viewReviews);return}const reviewSortButton=e.target.closest('[data-review-sort]');if(reviewSortButton){const key=reviewSortButton.dataset.reviewSort;if(reviewSort===key)reviewSortDir=reviewSortDir==='asc'?'desc':'asc';else{reviewSort=key;reviewSortDir=key==='name'?'asc':'desc'}renderReviews();return}const reviewFlagButton=e.target.closest('[data-review-flag]');if(reviewFlagButton){reviewFlag=reviewFlagButton.dataset.reviewFlag;renderReviews();return}if(e.target.closest('#reviewFilterButton')){document.querySelector('#reviewAmount').focus();showToast('Adjust the review-count slider to filter firms');return}const pmode=e.target.closest('[data-payout-mode]');if(pmode){payoutMode=pmode.dataset.payoutMode;payoutPage=1;renderPayoutView();return}const pcat=e.target.closest('[data-payout-category]');if(pcat){payoutCategory=pcat.dataset.payoutCategory;payoutPage=1;renderPayouts();return}const pp=e.target.closest('[data-payout-page]');if(pp){payoutPage=Number(pp.dataset.payoutPage);renderPayouts();document.querySelector('#payouts').scrollIntoView({behavior:'smooth',block:'start'});return}const pn=e.target.closest('[data-payout-nav]');if(pn&&!pn.disabled){payoutPage+=pn.dataset.payoutNav==='next'?1:-1;renderPayouts();document.querySelector('#payouts').scrollIntoView({behavior:'smooth',block:'start'});return}const pd=e.target.closest('[data-payout-detail]');if(pd){openPayoutFirmDetail(pd.dataset.payoutDetail);return}const dt=e.target.closest('[data-detail-timeframe]');if(dt){payoutDetailTimeframe=dt.dataset.detailTimeframe;payoutDetailPage=1;renderPayoutDetail();return}const dp=e.target.closest('[data-detail-page]');if(dp){payoutDetailPage=Number(dp.dataset.detailPage);renderPayoutDetail();return}const dn=e.target.closest('[data-detail-nav]');if(dn&&!dn.disabled){payoutDetailPage+=dn.dataset.detailNav==='next'?1:-1;renderPayoutDetail();return}if(e.target.closest('[data-delay-report]')){openModal('#delayReportModal');return}if(e.target.closest('[data-payout-methodology]')){openModal('#payoutMethodModal');return}const pv=e.target.closest('[data-payout-view]');if(pv){e.preventDefault();payoutView=pv.dataset.payoutView;payoutQuery='';openPage('payouts',{configure:false,scroll:!pv.closest('#payouts')});renderPayoutView();return}const ps=e.target.closest('[data-payout-sort]');if(ps){const key=ps.dataset.payoutSort;if(payoutSort===key)payoutSortDir=payoutSortDir==='asc'?'desc':'asc';else{payoutSort=key;payoutSortDir=key==='firm'||key==='rank'||key==='methods'||key==='latest'?'asc':'desc'}renderPayouts();return}const cp=e.target.closest('[data-challenge-page]');if(cp){challengePage=Number(cp.dataset.challengePage);renderChallenges();document.querySelector('#challengesPage').scrollIntoView({behavior:'smooth',block:'start'});return}const cn=e.target.closest('[data-challenge-nav]');if(cn&&!cn.disabled){challengePage+=cn.dataset.challengeNav==='next'?1:-1;renderChallenges();document.querySelector('#challengesPage').scrollIntoView({behavior:'smooth',block:'start'});return}const cb=e.target.closest('[data-challenge-buy]');if(cb){const link=cb.dataset.buyLink.trim();if(link){const opened=window.open(link,'_blank','noopener,noreferrer');if(opened)opened.opener=null}else{const terms=cb.closest('.challenge-row').querySelector('.challenge-terms');terms.hidden=false;copyCode();showToast('LENZ copied — check the offer terms')}return}const c=e.target.closest('[data-copy]');if(c){copyCode();return}const of=e.target.closest('[data-offer-filter]');if(of){offersFilter=of.dataset.offerFilter;document.querySelectorAll('[data-offer-filter]').forEach(b=>b.classList.toggle('on',b===of));renderOfferList();return}const more=e.target.closest('[data-offer-more]');if(more){const group=more.closest('.offer-group'),panel=group.querySelector('.offer-additional-rows'),name=group.dataset.offerGroup;panel.hidden=!panel.hidden;group.classList.toggle('expanded',!panel.hidden);more.setAttribute('aria-expanded',String(!panel.hidden));more.innerHTML=`More ${more.dataset.moreCount} <span aria-hidden="true">${panel.hidden?'⌄':'⌃'}</span>`;if(panel.hidden)expandedOfferGroups.delete(name);else expandedOfferGroups.add(name);return}const apply=e.target.closest('[data-apply]');if(apply){const buyLink=apply.dataset.buyLink.trim();if(buyLink){const opened=window.open(buyLink,'_blank','noopener,noreferrer');if(opened)opened.opener=null}else{copyCode();showToast('LENZ copied — check the offer terms')}return}const a=e.target.closest('[data-offer-page]');if(a){offerPage=(offerPage+(a.dataset.offerPage==='next'?1:-1)+2)%2;renderOffers();return}const od=e.target.closest('[data-offer-dot]');if(od){offerPage=Number(od.dataset.offerDot);renderOffers();return}const vd=e.target.closest('[data-video-dot]');if(vd){videoIndex=Number(vd.dataset.videoDot);renderVideos();return}const preferred=e.target.closest('[data-set-favorite]');if(preferred){const name=preferred.dataset.setFavorite;if(!favorites.has(name)){favorites.clear();favorites.add(name)}renderFavoriteFirms();renderMain();showToast(`${name} is your favorite`);return}const f=e.target.closest('[data-favorite]');if(f){const name=f.dataset.favorite;if(!favorites.has(name)){favorites.clear();favorites.add(name)}renderMain();renderFavoriteFirms();showToast(`${name} is your favorite`);return}const filter=e.target.closest('[data-filter]');if(filter){currentFilter=filter.dataset.filter;if(currentFilter==='popular'){sortKey='favorites';sortDir='desc'}else if(currentFilter==='all'){sortKey='rank';sortDir='asc'}document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('on',b===filter));renderMain();return}const sorter=e.target.closest('[data-sort]');if(sorter){const key=sorter.dataset.sort;if(sortKey===key)sortDir=sortDir==='asc'?'desc':'asc';else{sortKey=key;sortDir=key==='rank'?'asc':'desc'}renderMain();return}const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;renderMain();return}const m=e.target.closest('[data-market]');if(m){selectMarket(m.dataset.market);return}const mj=e.target.closest('[data-market-jump]');if(mj){selectMarket(mj.dataset.marketJump);return}if(e.target.closest('[data-methodology]')){openModal('#methodModal');return}if(e.target.closest('[data-close-modal]')){closeModals();return}const anchor=e.target.closest('a[href^="#"]');if(anchor){const route=LEGACY_ROUTES[anchor.getAttribute('href').slice(1)];if(route){e.preventDefault();openPage(route);return}}if(e.target.classList.contains('modal'))closeModals()});
document.addEventListener('keydown',e=>{const profileName=e.target.closest?.('[data-firm-profile]');if(profileName&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openFirmProfile(profileName.dataset.firmProfile);return}if(e.key==='Escape')closeModals()});
window.addEventListener('hashchange',()=>openPage(pageFromHash(),{replace:true,scroll:true}));
function runGlobalSearch(value,source){query=value.trim().toLowerCase();document.querySelectorAll('#globalSearch,#mobileSearch').forEach(input=>{if(input!==source)input.value=value});openPage('best-sellers',{configure:false});renderMain()}
document.querySelector('#globalSearch').addEventListener('input',e=>runGlobalSearch(e.target.value,e.target));
document.querySelector('#mobileSearch').addEventListener('input',e=>runGlobalSearch(e.target.value,e.target));
document.querySelector('#videoPrev').addEventListener('click',()=>{videoIndex=(videoIndex+videos.length-1)%videos.length;renderVideos()});
document.querySelector('#videoNext').addEventListener('click',()=>{videoIndex=(videoIndex+1)%videos.length;renderVideos()});
document.querySelector('#viewAll').addEventListener('click',e=>{e.preventDefault();query='';currentFilter='all';sortKey='rank';sortDir='asc';document.querySelectorAll('#globalSearch,#mobileSearch').forEach(input=>{input.value=''});document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('on',b.dataset.filter==='all'));renderMain()});
['challengeAsset','challengeSize','challengeSteps','challengeSort'].forEach(id=>document.querySelector('#'+id).addEventListener('change',e=>{if(id==='challengeAsset')challengeAsset=e.target.value;else if(id==='challengeSize')challengeSize=e.target.value;else if(id==='challengeSteps')challengeSteps=e.target.value;else challengeSort=e.target.value;challengePage=1;renderChallenges()}));
document.querySelector('#challengeSearch').addEventListener('input',e=>{challengeQuery=e.target.value.trim().toLowerCase();challengePage=1;renderChallenges()});
document.querySelector('#offersSearch').addEventListener('input',e=>{offersQuery=e.target.value.trim().toLowerCase();renderOfferList()});
document.querySelector('#reviewAmount').addEventListener('input',e=>{reviewMinimum=Number(e.target.value);document.querySelector('#reviewAmountValue').textContent=reviewMinimum===0?'0+':`${reviewMinimum>=1000?`${reviewMinimum/1000}K`:reviewMinimum}+`;renderReviews()});
document.querySelector('#favoriteSearch').addEventListener('input',e=>{favoriteQuery=e.target.value.trim().toLowerCase();renderFavoriteFirms()});
document.querySelector('#comparePicker').addEventListener('change',e=>{const select=e.target.closest('[data-compare-slot]');if(!select)return;compareSelections[Number(select.dataset.compareSlot)]=select.value;renderCompare()});
document.querySelector('#spreadsSearch').addEventListener('input',renderSpreads);
document.querySelector('#heroFirmCount').textContent=TRUSTPILOT_FIRMS.length.toLocaleString();
document.querySelector('#heroChallengeCount').textContent=CHALLENGES_DATA.length.toLocaleString();
document.querySelector('#heroOfferCount').textContent=forexOffers().length.toLocaleString();
const forexPayoutFirmCount=new Set([...(PAYOUT_DATA.latest_24h||[]),...(PAYOUT_DATA.weekly?.rows||[]),...(PAYOUT_DATA.monthly?.rows||[])].filter(x=>FOREX_NAMES.has(payoutCanonicalName(x.firm))).map(x=>payoutCanonicalName(x.firm))).size;
document.querySelector('#heroPayoutFirmCount').textContent=forexPayoutFirmCount.toLocaleString();
renderOfferList();
decorateFirmNames();
bindHomeForm();
renderOffers();renderFutures();renderMain();renderChallenges();renderReviews();renderFavoriteFirms();renderVideos();renderCompare();renderSpreads();renderPayoutView();routeFromHash();

// Interactive Modal Handlers
document.addEventListener('submit', function(e) {
  if (e.target && e.target.id === 'vipAccessForm') {
    e.preventDefault();
    const email = document.getElementById('vipEmail')?.value;
    if (email) {
      try { localStorage.setItem('pfl_vip_user', email); } catch (_) {}
      const succ = document.getElementById('vipSuccess');
      if (succ) succ.style.display = 'block';
      setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('VIP deal alerts activated!'); }, 1800);
    }
  }
  if (e.target && e.target.id === 'traderReviewForm') {
    e.preventDefault();
    const succ = document.getElementById('reviewSubmitSuccess');
    if (succ) succ.style.display = 'block';
    setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('Trader review submitted for moderation!'); }, 1800);
  }
  if (e.target && e.target.id === 'delayReportForm') {
    e.preventDefault();
    const succ = document.getElementById('delayReportSuccess');
    if (succ) succ.style.display = 'block';
    setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('Delay report logged for verification!'); }, 1800);
  }
});

